using System;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class ConfigurePajeroV6Audio {
public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play first");AssetDatabase.Refresh();var car=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var audio=car.GetComponent<VehicleAudio>();if(audio==null)throw new Exception("Missing shared vehicle audio");string path="Assets/Game/Audio/PajeroV6/Pajero V6 Audio.asset";var p=AssetDatabase.LoadAssetAtPath<VehicleAudioProfile>(path);if(p==null){p=UnityEngine.Object.Instantiate(audio.profile);AssetDatabase.CreateAsset(p,path);}p.name="Pajero V6 Audio";p.idleRpm=850;p.maximumRpm=6800;p.engineVolume=.72f;p.masterVolume=.85f;p.engineResponse=18;p.minDistance=6;p.maxDistance=70;p.engineSpatialBlend=.85f;p.rpmResponse=18;p.loadResponse=9;p.startupBlendSeconds=2.3f;p.engineStart=Clip("Start");p.brakeAir=null;p.maximumRecordedPitch=1.65f;p.minimumRecordedPitch=.55f;
string[] names={"Idle","Low","Mid","High","Redline"};float[] rpm={850,1500,3000,4500,6500};p.engineBands=new VehicleEngineAudioBand[names.Length];for(int i=0;i<names.Length;i++)p.engineBands[i]=new VehicleEngineAudioBand{name=names[i],referenceRpm=rpm[i],coast=Clip(names[i]+"Coast"),loaded=Clip(names[i]+"Load"),gain=i==0?.75f:.9f};p.idle=p.engineBands[0].coast;p.load=p.engineBands[2].loaded;audio.profile=p;audio.idle.clip=p.idle;audio.load.clip=p.load;EditorUtility.SetDirty(p);EditorUtility.SetDirty(audio);EditorUtility.SetDirty(audio.idle);EditorUtility.SetDirty(audio.load);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(car.gameObject.scene);if(!EditorSceneManager.SaveScene(car.gameObject.scene))throw new Exception("Scene save failed");return "Saved shared VehicleAudio + Pajero V6 Audio profile; 5 RPM bands x coast/load, recorded startup. Old diesel engine replaced; no pneumatic brake sound.";}
static AudioClip Clip(string name){string path="Assets/Game/Audio/PajeroV6/"+name+".wav";var importer=AssetImporter.GetAtPath(path) as AudioImporter;if(importer==null)throw new Exception("Missing "+path);importer.forceToMono=true;var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.DecompressOnLoad;settings.compressionFormat=AudioCompressionFormat.PCM;settings.preloadAudioData=true;importer.defaultSampleSettings=settings;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<AudioClip>(path);}
}
